      "paper": {
        "corpusId": "273682946",
        "title": "Generative AI Policy: A Pedagogical Communication Tool and Virtue Ethics Gateway",
        "authors": [
          "Cara Haderlie"
        ],
        "openAccessInfo": {
          "license": "CCBY",
          "status": "HYBRID",
          "disclaimer": "Notice: This snippet is extracted from the open access paper or abstract available at https://api.unpaywall.org/v2/10.1145/3641237.3691652?email=<INSERT_YOUR_EMAIL> or https://doi.org/10.1145/3641237.3691652, which is subject to the license by the author or copyright owner provided with this content. Please go to the source to verify the license and copyright information for your use."
        }
